CREATE TABLE Users(Id int IDENTITY PRIMARY KEY,FullName nvarchar(100) NOT NULL,Email nvarchar(254) NOT NULL UNIQUE,PasswordHash nvarchar(300) NOT NULL,Role nvarchar(20) NOT NULL CHECK(Role IN('Admin','Teacher','Accountant','Parent','Student')),IsActive bit NOT NULL DEFAULT 1,FailedLogins int NOT NULL DEFAULT 0,LockedUntil datetime2 NULL,SecurityVersion int NOT NULL DEFAULT 1,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Classes(Id int IDENTITY PRIMARY KEY,Name nvarchar(80) NOT NULL,Section nvarchar(20) NOT NULL,TeacherId int NOT NULL REFERENCES Users(Id),CONSTRAINT UQ_Class UNIQUE(Name,Section));
CREATE TABLE Students(Id int IDENTITY PRIMARY KEY,AdmissionNumber nvarchar(30) NOT NULL UNIQUE,FullName nvarchar(100) NOT NULL,BirthDate date NOT NULL,ClassId int NOT NULL REFERENCES Classes(Id),GuardianName nvarchar(150) NULL,GuardianPhone nvarchar(30) NULL,ParentUserId int NULL REFERENCES Users(Id),UserId int NULL REFERENCES Users(Id),IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE UNIQUE INDEX UQ_StudentUser ON Students(UserId) WHERE UserId IS NOT NULL;
CREATE INDEX IX_StudentClass ON Students(ClassId,IsActive);
CREATE TABLE Attendance(Id int IDENTITY PRIMARY KEY,StudentId int NOT NULL REFERENCES Students(Id),Day date NOT NULL,Status nvarchar(10) NOT NULL CHECK(Status IN('Present','Absent','Late','Excused')),RecordedBy int NOT NULL REFERENCES Users(Id),CONSTRAINT UQ_Attendance UNIQUE(StudentId,Day));
CREATE TABLE Invoices(Id int IDENTITY PRIMARY KEY,StudentId int NOT NULL REFERENCES Students(Id),Description nvarchar(150) NOT NULL,Amount decimal(12,2) NOT NULL CHECK(Amount>0),DueDate date NOT NULL,CreatedBy int NOT NULL REFERENCES Users(Id),CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Payments(Id int IDENTITY PRIMARY KEY,InvoiceId int NOT NULL REFERENCES Invoices(Id),Amount decimal(12,2) NOT NULL CHECK(Amount>0),Reference nvarchar(80) NOT NULL UNIQUE,RecordedBy int NOT NULL REFERENCES Users(Id),PaidAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Exams(Id int IDENTITY PRIMARY KEY,ClassId int NOT NULL REFERENCES Classes(Id),Title nvarchar(100) NOT NULL,Subject nvarchar(80) NOT NULL,MaxMarks int NOT NULL CHECK(MaxMarks BETWEEN 1 AND 1000),ExamDate date NOT NULL,CreatedBy int NOT NULL REFERENCES Users(Id));
CREATE TABLE Results(Id int IDENTITY PRIMARY KEY,ExamId int NOT NULL REFERENCES Exams(Id),StudentId int NOT NULL REFERENCES Students(Id),Marks decimal(7,2) NOT NULL CHECK(Marks>=0),RecordedBy int NOT NULL REFERENCES Users(Id),CONSTRAINT UQ_Result UNIQUE(ExamId,StudentId));
CREATE TABLE AuditLogs(Id bigint IDENTITY PRIMARY KEY,ActorId int NOT NULL REFERENCES Users(Id),Action nvarchar(80) NOT NULL,Entity nvarchar(80) NOT NULL,EntityId int NULL,OccurredAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
